// Petshop Rinkinių Gyvūno Filtras v1
// Rinkinių kategorijose (rinkiniai + konservu/skanestu/kramtalu-rinkiniai) rodo Šunims/Katėms perjungiklį
// ir filtruoja užklausą per pa_gyvuno_rusis. Rodo tik tuos gyvūnus, kurie kategorijoje realiai yra.

if (!function_exists('petshop_rinkiniu_cats')) {
    function petshop_rinkiniu_cats(){
        return array('rinkiniai','konservu-rinkiniai','skanestu-rinkiniai','kramtalu-rinkiniai');
    }
}

// 1. Užklausos filtravimas pagal ?gyvunas=
add_action('pre_get_posts', function($q){
    if (is_admin() || !$q->is_main_query()) return;
    if (!$q->is_tax('product_cat')) return;
    $slug = $q->get('product_cat');
    if (!in_array($slug, petshop_rinkiniu_cats(), true)) return;
    $g = isset($_GET['gyvunas']) ? sanitize_key($_GET['gyvunas']) : '';
    if ($g === 'sunims' || $g === 'katems') {
        $tq = (array) $q->get('tax_query');
        $tq[] = array('taxonomy'=>'pa_gyvuno_rusis','field'=>'slug','terms'=>$g);
        $q->set('tax_query', $tq);
    }
});

// 2. Perjungiklio atvaizdavimas
add_action('woocommerce_before_shop_loop', function(){
    if (!function_exists('is_product_category') || !is_product_category()) return;
    $term = get_queried_object();
    if (!$term || !in_array($term->slug, petshop_rinkiniu_cats(), true)) return;

    // kokie gyvūnai realiai yra šioje kategorijoje
    $present = array();
    foreach (array('sunims'=>'Šunims','katems'=>'Katėms') as $gslug=>$glabel) {
        $ids = get_posts(array(
            'post_type'=>'product','post_status'=>'publish','fields'=>'ids','posts_per_page'=>1,
            'tax_query'=>array('relation'=>'AND',
                array('taxonomy'=>'product_cat','field'=>'slug','terms'=>$term->slug),
                array('taxonomy'=>'pa_gyvuno_rusis','field'=>'slug','terms'=>$gslug),
            ),
        ));
        if (!empty($ids)) $present[$gslug] = $glabel;
    }
    if (count($present) < 2) return; // nėra ką filtruoti

    $base = get_term_link($term);
    if (is_wp_error($base)) return;
    $cur = isset($_GET['gyvunas']) ? sanitize_key($_GET['gyvunas']) : '';

    echo '<div class="psc-animal-filter">';
    echo '<span class="psc-af-label">Kam skirta:</span>';
    // Visi
    $active = ($cur==='') ? ' psc-af-active' : '';
    echo '<a href="'.esc_url($base).'" class="psc-af-btn'.$active.'">Visi</a>';
    foreach ($present as $gslug=>$glabel) {
        $active = ($cur===$gslug) ? ' psc-af-active' : '';
        $url = add_query_arg('gyvunas', $gslug, $base);
        echo '<a href="'.esc_url($url).'" class="psc-af-btn'.$active.'">'.esc_html($glabel).'</a>';
    }
    echo '</div>';
    ?>
    <style>
    .psc-animal-filter{
        display:flex; align-items:center; gap:10px; flex-wrap:wrap; margin:0 0 22px;
    }
    .psc-af-label{ font-weight:600; font-size:14px; color:#444; margin-right:2px; }
    .psc-af-btn{
        display:inline-block; text-decoration:none; font-size:14px; font-weight:600;
        color:#2f5a3a !important; background:#eef5f0; border:2px solid transparent;
        padding:8px 18px; border-radius:999px; transition:all .12s ease;
    }
    .psc-af-btn:hover{ background:#dfeee4; color:#2f5a3a !important; }
    .psc-af-active{
        background:#2f5a3a; color:#fff !important; border-color:#2f5a3a;
    }
    .psc-af-active:hover{ background:#2f5a3a; color:#fff !important; }
    </style>
    <?php
}, 8);

